"""Base collaborations of an environment generated by the base Agent: one natural collaboration per TRAIN case, with
the standalone assessment and the Agent-side states (src/agentclinic/trajectory.py: collaborate), under the
environment's protocol.
"""

from __future__ import annotations

import argparse
import json
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

from src.agentclinic.pipeline import Appender
from src.common.config import read_config

ROOT = Path(__file__).resolve().parents[1]


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--env", required=True)
    parser.add_argument("--policy-from", required=True, help="a resolved main config whose policy, devices and rollout are used")
    args = parser.parse_args()
    from src.agentclinic.protocol import protocol_spec
    from src.agentclinic.runtime import build_clinic, load_policy
    from src.agentclinic.trajectory import collaborate

    source = read_config(ROOT / args.env)
    out = ROOT / source["output_dir"] / "base_trajectories.jsonl"
    if out.exists() and out.stat().st_size:
        partial = Path(str(out) + ".partial")
        if not partial.exists():
            raise SystemExit(f"{out} exists; base trajectories are written once")
    config = json.loads((ROOT / args.policy_from).read_text(encoding="utf-8"))
    config = dict(config, output_dir=source["output_dir"], environment=dict(config["environment"], config=args.env))
    spec = protocol_spec(source["protocol"])
    model, tokenizer = load_policy(config["policy"], None, trainable=False, device=config["devices"]["policy"])
    clinic = build_clinic(config, ROOT, model, tokenizer)
    rows = Appender(Path(str(out) + ".partial"), key=lambda r: r["case_id"])
    train = sorted(k for k, c in clinic.cases.items() if c["split"] == "train")

    def one(case_id):
        if case_id not in rows.keys:
            rows.add(collaborate(clinic.cases[case_id], [], clinic.runtime, clinic.judge, spec=spec, max_attempts=3,
                                 trajectory_id=f"{case_id}:base", history_id=f"{case_id}:agentfirst", iteration=0, checkpoint_id="base"))

    with clinic.generation(), ThreadPoolExecutor(config["rollout"]["workers"]) as pool:
        list(pool.map(one, train))
    rows_sorted = sorted(rows.rows, key=lambda r: r["case_id"])
    out.write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in rows_sorted), encoding="utf-8")
    Path(str(out) + ".partial").unlink()
    print(json.dumps({"written": str(out.relative_to(ROOT)), "cases": len(rows_sorted), "protocol": spec.name,
                      "correct": sum(r["is_correct"] for r in rows_sorted), "valid": sum(r["trajectory_status"] == "valid" for r in rows_sorted)}, indent=1))


if __name__ == "__main__":
    main()
